INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁钰", "aliases": ["明景帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明景帝，正統14年（1449年）九月，朱祁钰即皇帝位。", "biography": null, "status": "draft", "id": "beac1b51-89b3-5024-bf3a-2d45bc5afe2b"}, {"name": "江渊", "aliases": ["江淵"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰元年（1450年）八月，江渊以刑部侍郎兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "4c319c1c-fb8c-52d1-82ca-fd1b4cdab14e"}, {"name": "陈豫", "aliases": ["平江侯陳豫"], "era": "明", "birth_year": null, "death_year": null, "description": "陈豫奉命抚辑受灾军民。", "biography": null, "status": "draft", "id": "2865c66f-a031-574e-b989-effec6c8e1f6"}, {"name": "王文（明代内阁大学士）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰3年（1452年）十月，王文以太子太保、左都御史身份入阁。", "biography": null, "status": "draft", "id": "0c5a5869-dc9f-5893-b3a4-cbe279406582"}, {"name": "马昂", "aliases": ["馬昂"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）五月，马昂出任都察院长官，外出巡抚山西。", "biography": null, "status": "draft", "id": "4c756f57-201a-5770-b7a5-670042269b3e"}, {"name": "思机发", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "思机发为明军征讨对象。", "biography": null, "status": "draft", "id": "4b70c1c9-54ce-526f-96a9-c56865625ed0"}, {"name": "方瑛", "aliases": ["參將方瑛"], "era": "明", "birth_year": null, "death_year": null, "description": "方瑛参与贵州战事。", "biography": null, "status": "draft", "id": "02981879-a0e2-5f34-81d2-beadecd41264"}, {"name": "章纶", "aliases": ["章綸"], "era": "明", "birth_year": null, "death_year": null, "description": "章纶因上奏请恢复储位而被下狱。", "biography": null, "status": "draft", "id": "575a8a1a-e1fc-564b-90c7-100e40788aa2"}, {"name": "钟同", "aliases": ["鍾同", "鐘同"], "era": "明", "birth_year": null, "death_year": null, "description": "钟同因上奏请恢复储位而被下狱。", "biography": null, "status": "draft", "id": "424bc66c-e972-5b36-90b0-7a5efc9acf79"}, {"name": "朱见深", "aliases": ["明宪宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宪宗，天順8年（1464年）正月，朱见深即皇帝位。", "biography": null, "status": "draft", "id": "71fde383-1de5-538d-bb25-2cc9e4cc7d1c"}, {"name": "刘广衡", "aliases": ["劉廣衡"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）八月，刘广衡出任刑部尚书。", "biography": null, "status": "draft", "id": "e8cc928c-92be-569b-86b3-362f592a460d"}, {"name": "也先", "aliases": ["瓦剌太师也先"], "era": "明", "birth_year": null, "death_year": null, "description": "也先所部为明廷防备对象。", "biography": null, "status": "draft", "id": "d9af0d41-e6b4-5de2-9de3-32e0f8826f3c"}, {"name": "阿剌（瓦剌知院）", "aliases": ["阿剌知院"], "era": "明", "birth_year": null, "death_year": null, "description": "阿剌（瓦剌知院）本纪记其杀死也先。", "biography": null, "status": "draft", "id": "94fef914-0ebc-5d19-b739-f3a9abbdce74"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "本纪记黄河龙门至芮城段水清", "description": "景泰五年正月戊午，本纪记从龙门到芮城的黄河水一度变清。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年正月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0af15595-3a34-5b10-98bb-1888ff585d9c"}, {"title": "明景帝在南郊祭祀天地", "description": "景泰五年正月甲子，明景帝朱祁钰在南郊举行祭祀天地的大典。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年正月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "daca4de9-d534-528a-946e-f640ffb793b6"}, {"title": "明廷停办福州和建宁银场", "description": "景泰五年正月壬申，明廷下令停办福州、建宁的银场。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年正月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "596f665f-4a52-510f-9dcf-f2c495fbe353"}, {"title": "江渊前往山东抚安地方", "description": "景泰5年（1454年）正月，江渊前往山东抚安地方。", "start_year": 1454, "end_year": 1454, "time_original": "景泰5年（1454年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "90b9c93e-bcf0-59db-86ca-669496e6d74d"}, {"title": "明景帝因雨晴失时下诏修省，征求直言", "description": "景泰五年二月乙巳，明景帝以雨晴失时为由，下诏修省，并请臣下直言政事。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年二月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "356008e9-e36e-5a26-b393-d02b6ef313e5"}, {"title": "明廷授予孙贤等人进士资格", "description": "景泰五年三月壬子，明廷授予孙贤等人不同等第的进士资格。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年三月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9105a2e-e0f0-5aac-92b4-066a930a31b5"}, {"title": "江渊奉命赈济淮北饥民", "description": "景泰五年三月辛酉，朝廷命学士江渊赈济淮北的饥民。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年三月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "94d35855-b7d1-5dc2-932b-508dcec1dab8"}, {"title": "王文奉命抚恤南直隶百姓", "description": "景泰五年三月，王文奉命到南直隶一带抚恤百姓。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9ffb7c4b-5371-5951-b5f4-dc6ac7f020a5"}, {"title": "马昂在泷水击败起事瑶民", "description": "景泰五年三月甲子，总督两广的副都御史马昂率军击败泷水一带起事的瑶民。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年三月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b12cc910-6cf1-5378-8d52-62f495662b16"}, {"title": "本纪记缅甸向明廷移交思机发", "description": "景泰五年三月庚辰，《景帝本纪》记缅甸将拘捕的麓川首领思机发交给明廷。《麓川平缅传》还另述先前的捕获与移交后送京等阶段。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年三月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4fbe6f1d-3c04-579f-917b-5936ce1c76d0"}, {"title": "本纪记景泰五年四月初一发生日食", "description": "景泰五年四月初一，《景帝本纪》记发生日食。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年四月壬午朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "84f56894-86d7-5105-ba97-ec5f3f83d6c1"}, {"title": "方瑛击败草塘起事苗民", "description": "景泰五年四月辛卯，方瑛率明军在草塘击败起事的苗民。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年四月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1086f6a0-f932-59e7-b4af-16aa23e6b24b"}, {"title": "方瑛因战功获封南和伯", "description": "景泰五年四月条记，方瑛在草塘获胜，朝廷封他为南和伯。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2abe2880-694c-520b-9825-47df106b00f9"}, {"title": "章纶、钟同因请求恢复朱见深太子身份被下狱", "description": "景泰五年五月甲子，礼部郎中章纶、御史钟同因上奏请求让沂王朱见深重新成为皇太子，被关入锦衣卫监狱。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年五月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f2edd82-6a7c-5c1a-b988-93799fbf7a9e"}, {"title": "明廷复核在押人员案件", "description": "景泰五年六月戊子，明廷复核在押人员的案件。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年六月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "df58e795-1340-5727-9ccb-50aed2132adb"}, {"title": "明廷赈济南直隶水灾", "description": "景泰五年七月癸酉，明廷赈济南直隶遭遇水灾的地区。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年七月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d24008c5-d342-5693-810b-c262b6c87a0c"}, {"title": "明廷恢复巡抚赴京议事", "description": "景泰五年八月丁酉，朝廷恢复各地巡抚进京议事的安排。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年八月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "82f3cd6f-5d81-5cb0-a0f7-53869dc06e31"}, {"title": "明廷免除苏松常扬杭嘉湖漕粮二百余万石", "description": "景泰五年九月壬戌，朝廷减免苏州、松江、常州、扬州、杭州、嘉兴、湖州应缴的漕粮，共二百余万石。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年九月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aca25102-51f7-553d-b147-4f8d65eb643c"}, {"title": "刘广衡巡抚浙江和福建，专管征讨", "description": "景泰五年十月庚辰，明廷派副都御史刘广衡巡抚浙江、福建，专门负责征讨当地起事者。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年十月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b639e038-1f06-5681-80f5-43af7ba7a191"}, {"title": "明廷停止苏松常镇织造采办", "description": "景泰五年十一月戊午，朝廷停止向苏州、松江、常州、镇江征办织造和采购事务。", "start_year": 1454, "end_year": 1454, "time_original": "景泰五年十一月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cda32efd-f6a0-5a56-906e-e23c761d7149"}, {"title": "明廷豁免南直隶、浙江灾区税粮", "description": "景泰五年十二月，明廷免除南直隶和浙江受灾地区应缴的税粮。 按原历纪年，事情发生在公元1454至1455年之间。", "start_year": null, "end_year": null, "time_original": "景泰五年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "29a3f1d7-b556-5d70-b189-7499ff0c63d2"}, {"title": "安南、琉球中山和爪哇入贡", "description": "景泰五年，安南、琉球中山和爪哇入贡。 按原历纪年，事情发生在公元1454至1455年之间。", "start_year": null, "end_year": null, "time_original": "景泰五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c98ea114-af45-5c2b-91f8-e0146fd1004c"}, {"title": "本纪记也先被知院阿剌杀死", "description": "《景帝本纪》在景泰五年年末的记事中说，瓦剌可汗也先被知院阿剌杀死。 按原历纪年，事情发生在公元1454至1455年之间。", "start_year": null, "end_year": null, "time_original": "景泰五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b10310a1-bc27-5b2b-8921-074c2fe00620"}]'::jsonb)
